function UIClimbTowerMainDialog:InitData()
    local t = QuestConfMgr:GetInstance():GetAllTowerQuestIds()
    self._allCount = table.count(t)

    local lastId = checkNumber(towerQuestComponent:GetCurQuestId())
    local vo
    if lastId == 0 then
        vo = QuestConfMgr:GetInstance():GetFirstTowerQuestVo()
    else
        local nextId = QuestConfMgr:GetInstance():GetNextTowerQuestId(lastId)
        --为0为关底
        if checkNumber(nextId) ~= 0 then
            vo = QuestConfMgr:GetInstance():GetQuestVoById(nextId)
        else
            vo = QuestConfMgr:GetInstance():GetQuestVoById(lastId)
        end
    end
    if vo then
        self._curQuestId = checkNumber(vo.id)
    end
    if checkNumber(self._lastPassId) > 0 then
        --用是否通关校验一下  防止周期变了
        if QuestConfMgr:GetInstance():IsPassQuest(self._lastPassId) then
            self._curQuestId = self._lastPassId
        end
    end 

    self._allQuestVos = {}
    local isFind = false
    local num = 0
    for k, v in pairs(t) do
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(v)
        table.insert(self._allQuestVos, vo)
        num = num + 1

        if checkNumber(self._curQuestId) == checkNumber(v) then
            self._curCount = num
            isFind = true
        end

        if num % 5 == 0 then
            if isFind then
                break
            else
                self._allQuestVos = {}
            end
        end
    end

    --self._curCount = table.keyof(t, checkString(self._curQuestId))
end

function UIClimbTowerMainDialog:FillSelf()
    CfUtils.FillText(self.TxtNumber, "<size=70>" .. self._curCount .. "</size>/" .. self._allCount)

    if not self._isInit then
        self.ListView:InitListView(table.count(self._allQuestVos), Bind(self, self.OnGetRoleCellByIndex))
        self._isInit = true
    else
        GameUtils.ReloadData(self.ListView, 0)
        GameUtils.ReloadData(self.ListView, table.count(self._allQuestVos))
    end

    self:StartTimeDown()

    self:FillQuestInfo()

    local num = towerQuestComponent:GetEndRemainingTime()
    local time = CfUtils.GetTimeHMS(num)
    CfUtils.FillText(self.Time, time)

    CfUtils.FillText(self.TxtNumber2, "<size=46><color=#ffffff>"..self._rewardsNum.."</size></color>/"..self._rewardCumulativeNum)

    local id = checkNumber(towerQuestComponent:GetCurQuestId())
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    local num1 = 0
    if vo then
        num1 = checkNumber(vo.storey)
    end

    num1 = math.floor(num1 / QuestConfMgr:GetInstance():GetClimbTowerQuickMultiple()) * QuestConfMgr:GetInstance():GetClimbTowerQuickAddTimes()

    if num1 >= QuestConfMgr:GetInstance():GetClimbTowerQuickMax() then
        num1 = QuestConfMgr:GetInstance():GetClimbTowerQuickMax()
    end

    CfUtils.FillText(self.LeftGroup.transform:Find("NextGetGroup/NextTotalNode/ImgNextBg/TxtNextNumber"), num1.."/"..QuestConfMgr:GetInstance():GetClimbTowerQuickMax())
    CfUtils.FillText(self.LeftGroup.transform:Find("NextGetGroup/NextTipsNode/ImgNextBg/TxtNextNumber"), "+"..QuestConfMgr:GetInstance():GetClimbTowerQuickAddTimes())

    local quickStory = towerQuestComponent:GetQuickQuestStory()
    CfUtils.SetActive(self.BtnFight, quickStory < self._curCount)
    CfUtils.SetActive(self.RightGroup.transform:Find("BtnQuickFight"), quickStory >= self._curCount)

    if quickStory >= self._curCount then
        CfUtils.FillText(self.RightGroup.transform:Find("BtnQuickFight/Button/TxtQuickLevel"), "01~"..quickStory)
    end
end

function UIClimbTowerMainDialog:FillQuestInfo()
    self:FillReward()
    self:FillBossInfo()

    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curQuestId)
    CfUtils.SetActive(self.FontStyleButton1, not isPass)
    CfUtils.SetActive(self.FontStyleButton2, isPass)
    if not isPass then
        local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._curQuestId)
        CfUtils.SetUISwitchText(self.FontStyleButton1.transform:Find("Text"), isUnlock and 1 or 2)
        CfUtils.SetUISwitchText(self.FontStyleButton1.transform:Find("Text2"), isUnlock and 1 or 2)
    end

    local passNum = self._clearanceRate[checkString(self._curQuestId)]
    if passNum then
        CfUtils.FillText(self.TxtNumberReach, "<size=73>"..passNum.."</size>%")
    end
end

function UIClimbTowerMainDialog:FillBossInfo()
    local t = QuestConfMgr:GetInstance():GetEnemysDataInfo(self._curQuestId)
    if not t then
        return
    end

    if self._lastPosPar then
        CfUtils.SetActive(self._lastPosPar, false)
    end

    local num = self:GetPosNum()
    local parGo = self["Role"..num]
    self._lastPosPar = parGo

    if isNull(parGo) then
        return
    end

    --boss排第一
    for i = 2, #t do
        if checkNumber(t[i].type) == Constants.RoleClass.Boss then
            local _t = t[1]
            t[1] = t[i]
            t[i] = _t
        end
    end
    local animRootGo = parGo.transform:Find("AnimRoot")
    for k, v in pairs(t) do
        local go = animRootGo.transform:Find("BtnRole"..k)
        if go then
            local path = CardConfMgr:GetInstance():GetMonstHeadIcon(v.id)
            CfUtils.FillImage(go.transform:Find("Btn/ImgRole/ImgRole"), path)
            KTool.SetActive(go, true)
        end
        SetButtonAction(go, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIBossDetailDialog, parameters = { levelId = self._curQuestId } })
        end)
    end

    CfUtils.PlayAnimator(animRootGo, "Go")
end

--开始倒计时
function UIClimbTowerMainDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local num = towerQuestComponent:GetEndRemainingTime()
        local time = CfUtils.GetTimeHMS(num)

        CfUtils.FillText(self.Time, time)
    end, CountDownTime, false, true)
end

function UIClimbTowerMainDialog:OnGetRoleCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._allQuestVos[index + 1]
    local cell = listView:NewListViewItem("Cell1")
    
    local scr = CfUtils.GetLuaScr(cell, UIClimbTowerMainCellNode)
    if scr then
        scr:Refresh(data, function()
           self:OnSelect(data)
        end)
        scr:FillCurInfo(checkNumber(self._curQuestId) == checkNumber(data.id))
    end
    return cell
end

function UIClimbTowerMainDialog:OnSelect(data)
    if checkNumber(self._curQuestId) == checkNumber(data.id) then
        return
    end
    local ind = CfUtils.GetTableValueKey(self._allQuestVos, "id", checkNumber(self._curQuestId))

    if checkNumber(ind) > 0 then
        local go = self.ListView:GetShownItemByItemIndex(ind - 1)
        local scr = CfUtils.GetLuaScr(go, UIClimbTowerMainCellNode)
        if scr then
            scr:FillSelect("Default")
            scr:FillCurInfo(false)
        end
    end

    self._curQuestId = data.id
    ind = CfUtils.GetTableValueKey(self._allQuestVos, "id", checkNumber(self._curQuestId))

    if checkNumber(ind) > 0 then
        local go = self.ListView:GetShownItemByItemIndex(ind - 1)
        local scr = CfUtils.GetLuaScr(go, UIClimbTowerMainCellNode)
        if scr then
            scr:FillSelect("Go")
            scr:FillCurInfo(true)
        end
    end

    self:FillQuestInfo()
    CfUtils.SetActive(self._lastPosPar, true)
    CfUtils.PlayAnimator(self._lastPosPar.transform:Find("AnimRoot"), "Go")
end

function UIClimbTowerMainDialog:FillReward()
    if checkNumber(self._curQuestId) == 0 then
        return
    end

    CfUtils.SetActive(self.RewardList, true)
    for i = 1, self.RewardList.childCount do
        CfUtils.SetActive(self.RewardList:GetChild(i - 1).gameObject, false)
    end

    local data = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curQuestId)
    for k, v in pairs(data) do
        local go = self.RewardList.transform:Find("go" .. k)
        if not go then
            go = CfUtils.InstantiateGo(self.GoodGroup, self.RewardList)
            go.name = "go" .. k
        end
        KTool.SetActive(go, true)
        CfUtils.RefeshGoodGo(go.transform:Find("GoodNode"), v.id, v.num, 0.64, nil, function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.id)
            if vo then
                GameUtils.ShowCommonTipsBoard(go, vo.name, nil, nil, v.id, false)
            end
        end)
    end
end

function UIClimbTowerMainDialog:OnBtnVideo()
    self.isReleaseAtlas = false
    towerQuestComponent:ClimbingTowerVideoReq(self._curQuestId)
end

function UIClimbTowerMainDialog:OnBtnQuick()
    towerQuestComponent:QuickReq(function(rewardsNum, clearanceRate)    
        self._rewardsNum = checkNumber(rewardsNum)
        self._clearanceRate = checkTable(clearanceRate)

        self:InitData()
        self:FillSelf()

        for i = 1, 5 do
            local go = self.ListView:GetShownItemByItemIndex(i - 1)
            local scr = CfUtils.GetLuaScr(go, UIClimbTowerMainCellNode)
            if scr then
                local data = self._allQuestVos[i]
                local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(data.id)
                local isPass = QuestConfMgr:GetInstance():IsPassQuest(data.id)
                local name = "Default"
                if checkNumber(KCookie.Get("EnterUIClimbTowerMainDialog")) == 1 then
                    if checkNumber(self._curQuestId) == checkNumber(data.id) then
                        name = "ChooseGo"
                    else
                        if isPass then
                            name = "CompletionGo"
                        else
                            name = "Go"
                        end
                    end
                else
                    if checkNumber(self._curQuestId) == checkNumber(data.id) then
                        name = "ChooseDefault"
                    else
                        if isPass then
                            name = "CompletionDefault"
                        else
                            name = "Default"
                        end
                    end
                end
    
                if checkNumber(KCookie.Get("EnterUIClimbTowerMainDialog")) == 1 then
                    CfUtils.PlayDelayShowAnimate(go.gameObject.transform:Find("ButtonNode/AnimRoot"), i, nil, nil, name)
                else
                    CfUtils.PlayAnimator(go.gameObject.transform:Find("ButtonNode/AnimRoot"), name)
                end
    
                if checkNumber(self._curQuestId) == checkNumber(data.id) and checkNumber(KCookie.Get("EnterUIClimbTowerMainDialog")) == 1 then
                    cs_coroutine.start(function()
                        coroutine.yield(WaitForSeconds(0.5))
                        scr:FillSelect("Go")
                    end)
                else
                    scr:FillSelect("Default")
                end
            end
        end
    end)
end

function UIClimbTowerMainDialog:OnBtnBattle()
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._curQuestId)
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._curQuestId)
    local isOpen = towerQuestComponent:IsOpen()

    if not isOpen then
        GameUtils.Toast(localize("当前未开放"))
    elseif isUnlock then
        if isPass then
            GameUtils.Toast(localize("已通关无法挑战"))
        else
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curQuestId } }, {
                { id = Constants.UITypeIds.UIClimbTowerMainDialog }
            })
        end
    else
        GameUtils.Toast(localize("关卡未解锁"))
    end
end

function UIClimbTowerMainDialog:GetPosNum()
    local t = QuestConfMgr:GetInstance():GetAllEnemyIds(self._curQuestId)
    if not t or table.count(t) <= 0 then
        return 1
    end

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if not vo then
        return 1
    end

    local num = table.count(t)
    if checkNumber(vo.monsteType) == Constants.RoleClass.Boss or checkNumber(vo.monsteType) == Constants.RoleClass.Elite then
        if num == 1 then
            return 7
        elseif num == 3 then
            return 8
        elseif num == 5 then
            return 9
        end
    else
        if num <= 6 then 
            return num
        end 
    end

    return 1
end

function UIClimbTowerMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isFinish1, isFinish2 = false, false
        GameUtils.Request(Interfaces.PlayerActionHome, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
            end

            local jsonData = response.data
            local actionInfo = jsonData.actionInfo
            for k, v in pairs(actionInfo) do
                if checkNumber(k) == Constants.SystemToggleIds.Id15 then   --爬塔
                    towerQuestComponent:Initial(v)
                end
            end

            isFinish1 = true
        end)    
        while not isFinish1 do
            coroutine.yield(Yielders.EndOfFrame)
        end
        self:InitData()

        GameUtils.Request(Interfaces.climbingTowerHome, { questId = self._curQuestId }, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local jsonData = response.data
            self._clearanceRate = checkTable(jsonData.clearanceRate)

            self._rewardsNum = checkNumber(jsonData.rewardsNum)
            self._rewardCumulativeNum = checkNumber(jsonData.rewardCumulativeNum)

            towerQuestComponent:SetRemainReportNum(checkNumber(jsonData.remainReportNum), checkNumber(jsonData.fastPassedStorey))
            isFinish2 = true
        end)

        while not isFinish2 or not isFinish1 do
            coroutine.yield(Yielders.EndOfFrame)
        end
    end))
    return coWait
end

function UIClimbTowerMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CS.Engine.Lib.KCookie.Set("TowerQuestLastPass", 0)
        if self._co ~= nil then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        
        if self.defaultOrthographic ~= nil then
            local cam = CS.Engine.UI.UIModule.RootCanvas.defaultCamera
            if not cam then
                return
            end
            cam.orthographic = self.defaultOrthographic
            cam.fieldOfView = self.defaultFieldOfView
        end

        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end
        CfUtils.SetUICameraProjection(true)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIClimbTowerMainDialog
